package com.darklandsmobile.grimreich.v1
import org.junit.jupiter.api.Assertions.*; import org.junit.jupiter.api.Test; import kotlin.random.Random
class LootMappingTest { @Test fun `loot entry maps to real item when present`(){ val sword=GrimBuilders.item(id="sword-01",name="Short Sword",rarity="uncommon"); val mapper=LootMapper(mapOf(sword.id to sword)); assertEquals("Short Sword",mapper.mapEntryToItem(GrimBuilders.lootEntry(sword.id,50))!!.name) } @Test fun `loot entry missing item returns null and does not crash`(){ val mapper=LootMapper(emptyMap()); assertNull(mapper.mapEntryToItem(GrimBuilders.lootEntry("missing",10))) } @Test fun `loot quantities respect min and max`(){ val item=GrimBuilders.item(id="potion",name="Potion"); val table=GrimBuilders.rewardTable(entries=listOf(GrimBuilders.lootEntry(item.id,100,2,5))); val mapper=LootMapper(mapOf(item.id to item)); val qty=mapper.rollReward(table,Random(999)).first().second; assertTrue(qty in 2..5) } }
